SELECT 

WHERE 1 = 1

    AND td.owner_id = #{query.dataScopeUserId}


    AND td.customer_id = #{query.customerId}


    AND td.opportunity_id = #{query.opportunityId}


    AND td.vehicle_id = #{query.vehicleId}


    AND td.owner_id = #{query.ownerId}


    AND td.status = #{query.status}


    AND (td.test_drive_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR c.customer_name LIKE CONCAT('%', #{query.keyword}, '%')
        OR v.vin LIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY td.planned_start_time DESC, td.id DESC

SELECT COUNT(1)
FROM t_test_drive
WHERE owner_id = #{ownerId}
  AND status IN ('PENDING_CONFIRM', 'SCHEDULED', 'RESCHEDULED', 'CHECKED_IN')
  AND planned_start_time < #{endTime}
  AND planned_end_time > #{startTime}

  AND id != #{excludeId}

